/// <summary>
/// Used to set up item Unit of measure convertion list
/// </summary>
[TFMDescription("Used to set up item Unit of measure convertion list")]
class MwmsLogicContextUnitOfMeasure extends TFMLogicContextFunctions
{

}

Method.Source:
protected void new()
{
    super();
    noOfInput = 0;
    outputType = TFMLogicContextTypes::Boolean;
}

public static MwmsLogicContextUnitOfMeasure Construct()
{
    MwmsLogicContextUnitOfMeasure uomSetup = new MwmsLogicContextUnitOfMeasure();
    return uomSetup;
}

[DataContract(classStr(TFMUnitOfMeasureContextContract))]
public Object process(ItemId _itemId = '')
{
    TFMUnitOfMeasureContextContract         contract = new TFMUnitOfMeasureContextContract();
    InventTable                             iTable = InventTable::find(_itemId);

    if (iTable)
    {
        contract.parmListOfUnitOfMeasure(TFMHelper::getConvertibleUnitList(iTable));
        contract.parmDefaultUnitId(iTable.inventUnitId());
    }

    return contract;
}
